        $join->setRelationMap($relationMap, $this->useAliasInSQL ? $this->getModelAlias() : null, $relationAlias);
        if ($previousJoin = $this->getPreviousJoin()) {
            $join->setPreviousJoin($previousJoin);
        }

        // add the ModelJoin to the current object
        if ($relationAlias) {
            $this->addAlias($relationAlias, $relationMap->getRightTable()->getName());
            $this->addJoinObject($join, $relationAlias);
        } else {
            $this->addJoinObject($join, 'Transferencia');
        }

        return $this;
    }

    /**
     * Use the Transferencia relation Transferencia object
     *
     * @see       useQuery()
     *
     * @param     string $relationAlias optional alias for the relation,
     *                                   to be used as main alias in the secondary query
     * @param     string $joinType Accepted values are null, 'left join', 'right join', 'inner join'
     *
     * @return   TransferenciaQuery A secondary query class using the current class as primary query
     */
    public function useTransferenciaQuery($relationAlias = null, $joinType = Criteria::LEFT_JOIN)
    {
        return $this
            ->joinTransferencia($relationAlias, $joinType)
            ->useQuery($relationAlias ? $relationAlias : 'Transferencia', 'TransferenciaQuery');
    }

    /**
     * Exclude object from result
     *
     * @param   Vinculada $vinculada Object to remove from the list of results
     *
     * @return VinculadaQuery The current query, for fluid interface
     */
    public function prune($vinculada = null)
    {
        if ($vinculada) {
            $this->addUsingAlias(VinculadaPeer::VINCULADA_ID, $vinculada->getVinculadaId(), Criteria::NOT_EQUAL);
        }

        return $this;
    }

}
